// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2001, "8-9", [{"author":"Л. Фёдорова","question":"«Зуб болел всё сильнее, и Витя, …, пошёл к зубному врачу». Как же Витя пошёл лечить зуб?","choices":["<em>скребя сердце</em>","<em>скрепя сердце</em>","<em>скрипя сердцем</em>","<em>скривя сердце</em>","<em>скрипя в сердце</em>."],"key":"Б","review":["К зубному врачу","Вите не хочется идти, но он всё-таки решается. Нужен оборот со значением «неохотно, переборов себя».","Пишем «скрепя сердце». Слово связано со «скрепить», а не со скрипом."]},{"author":"И. Рубанов","question":"Сколько неверно написанных слов в списке: <em>клеющий, бреющий, будующий, пресмыкающее, думающий</em>?","choices":["0","1","2","3","4."],"key":"Г","review":["Буквы в причастиях","От «клеить» получаем «клеящий». Слово «будущий» пишется без дополнительного ю, а животное называют «пресмыкающееся» — с -ся.","«Бреющий» и «думающий» написаны верно. Исправления требуются в трёх словах."]},{"author":"У. Синицына","question":"В результате соединения каких частей речи получилось имя доктора Айболита?","choices":["наречие + глагол","наречие + существительное","междометие + глагол","частица + глагол","существительное + существительное."],"key":"В","review":["Имя Айболита","Раздели имя так, как мог бы вскрикнуть пациент: «Ай! Болит!» Слово «ай» передаёт чувство боли.","«Ай» — междометие, «болит» — глагол. Их сочетание превратилось в имя доктора."]},{"author":"Л. Фёдорова","question":"Некоторые устойчивые словосочетания «помещают» животных в определённые места: [чувствовать себя] <em>как рыба в воде</em>, [бежать] <em>как крыса с тонущего корабля</em> и т. п. Вот пять животных: <em>белка, слон, собака, синица, журавль</em> — и пять мест: 1) <em>в руках</em>, 2) <em>в небе</em>, 3) <em>на сене</em>, 4) <em>в колесе</em>, 5) <em>в посудной лавке</em>. Расположите места в том порядке, в каком идут соответствующие им животные (например, ответ (А) означает, что белке соответствует «в руках», слону — «в посудной лавке» и т. д.).","choices":["1-5-2-3-4","3-5-2-4-1","4-1-2-5-3","4-5-3-1-2","5-4-1-3-2."],"key":"Г","review":["У каждого своё место","Белка вертится в колесе, слон оказывается в посудной лавке, а собака — на сене.","Синицу держат в руках, журавля ищут в небе. Записываем 4, 5, 3, 1, 2."]},{"author":"К. Кноп","question":"Согласно известной математической шутке, <em>такая крыса, которая бегает по углам и делит угол пополам, — это … .</em>","choices":["<em>бисектрисса</em>","<em>биссектрисса</em>","<em>бисектриса</em>","<em>бесектриса</em>","<em>биссектриса</em>."],"key":"Д","review":["Крыса на уроке геометрии","Шутка напоминает, что луч делит угол на две равные части. Его название завершается на -триса.","Проверяем обе позиции удвоения: «биссектриса» пишется с двумя с после и и с одной с в конце."]},{"author":"Е. Муравенко","question":"Кто написал сказку, название которой здесь зашифровано?","choices":["<em>Чуковский</em>","<em>Маршак</em>","<em>Носов</em>","<em>Волков</em>","<em>Драгунский</em>."],"key":"Г","review":["Сказка в ребусе","Л внутри О читается «в О Л», то есть «вол». Прибавь ш, а от слова «учебник» по двум запятым слева убери первые две буквы: получится «волшебник».","Расшифрованное название — «Волшебник Изумрудного города». Автор этой сказочной повести — Александр Волков."],"figure":{"condition":{"src":"assets/medvezhonok/2001/figures/8-9-06.webp","detailSrc":"assets/medvezhonok/2001/figures/8-9-06-detail.webp","alt":"Последовательность рисунков и знаков, образующая название сказки.","pixelWidth":882,"pixelHeight":117}}},{"author":"К. Кноп","question":"Исключите слово, которое принадлежит не к той категории поэтических терминов, что все остальные слова:","choices":["<em>ямб</em>","<em>эпиграмма</em>","<em>амфибрахий</em>","<em>гекзаметр</em>","<em>хорей</em>."],"key":"Б","review":["Стихотворные термины","Ямб, хорей и амфибрахий описывают чередование ударных и безударных слогов; гекзаметр — определённый стихотворный размер.","Эпиграмма — короткое насмешливое стихотворение, то есть жанр. Её можно написать разными размерами."]},{"author":"Л. Фёдорова","question":"В каких предложениях <em>казалось</em> и <em>кажется</em> являются вводными словами и требуют обособления? 1. <em>Казалось всё словно застыло.</em> 2. <em>Всё казалось словно застыло.</em> 3. <em>Мне всё кажется, что я здесь уже был.</em> 4. <em>Он кажется тут лишний.</em> 5. <em>Он тут кажется лишним.</em>","choices":["во всех","в 1, 2, 4","в 2, 4","в 4","в 1, 4."],"key":"Б","review":["Когда нужны запятые","В 1, 2 и 4 высказывание сохраняет смысл без «казалось» или «кажется»: «всё словно застыло», «он тут лишний». Здесь это вводная оценка говорящего.","В 3 «мне кажется» — основа главной части. В 5 «кажется лишним» — сказуемое. Нужные номера: 1, 2, 4."]},{"author":"Е. Муравенко","question":"Какова форма единственного числа именительного падежа существительного <em>ножищи</em>?","choices":["<em>ножище</em>","<em>ножища</em>","<em>ножищ</em>","слово употребляется только во мн. числе","<em>ножище</em> или <em>ножища</em> в зависимости от значения слова."],"key":"Д","review":["Большие ножи или ноги","Увеличительная форма от «нож» — «ножище», а от «нога» — «ножища». В обоих случаях во множественном числе можно встретить «ножищи».","Без контекста выбрать один из двух предметов нельзя. Единственное число зависит от значения."]},{"author":"А. Кадыкова","question":"В каком варианте все перечисленные слова обозначают рыб?","choices":["<em>марена, сурдинка, сурепка</em>","<em>мурена, сардинка</em>","<em>морена, сардинка, сарделька</em>","<em>морена, сурдинка</em>","<em>мурена, сардинка, сурепка</em>."],"key":"Б","review":["Слова, похожие на слух","Мурена — длинная морская рыба с мощными челюстями. Сардинка — небольшая рыба семейства сельдевых.","В этой паре оба слова обозначают рыб. Сурдинка, например, относится к музыкальным инструментам, а сурепка — растение."],"reviewedEdition":true},{"author":"Л. Фёдорова","question":"Какое слово образовано не так, как остальные?","choices":["<em>лоботряс</em>","<em>сердцеед</em>","<em>зубоскал</em>","<em>лизоблюд</em>","<em>людоед</em>."],"key":"Г","review":["Из чего сложено слово","«Лоботряс» трясёт лбом, «сердцеед» ест сердца в переносном смысле, «зубоскал» скалит зубы, «людоед» ест людей. В конце этих слов находится глагольная основа.","В «лизоблюд» порядок иной: сначала действие «лизать», потом предмет «блюдо»."]},{"author":"Е. Муравенко","question":"Как правильно сказать?","choices":["<em>надеть оба туфля</em>","<em>надеть обе туфли</em>","<em>одеть оба туфля</em>","<em>одеть обе туфли</em>","ни один из вариантов (А)–(Г) не верен."],"key":"Б","review":["Две туфли","Название одной туфли — «туфля», это слово женского рода. Поэтому нужна форма «обе».","Предмет одежды или обуви надевают, а одевают кого-нибудь. Получается «надеть обе туфли»."]},{"author":"Н. Муравенко","question":"Все приведённые ниже слова — устаревшие, но четыре устарели по одной причине, а одно — по другой. Какое?","choices":["<em>боярин</em>","<em>вече</em>","<em>армяк</em>","<em>ямщик</em>","<em>чело</em>."],"key":"Д","review":["Старое слово и старая вещь","Боярин, вече, армяк и ямщик называют исторические понятия, предмет одежды или профессию прежних времён.","Чело — старинное название лба. Сама часть тела никуда не исчезла, изменилось привычное название."]},{"author":"И. Рубанов","question":"Какое слово надо подставить вместо многоточия во фразу: <em>Нас не устраивает уровень двусторонних отношений наших стран, и мы сделаем все для его ...</em>?","choices":["<em>активизации</em>","<em>усиления</em>","<em>укрепления</em>","<em>улучшения</em>","<em>повышения</em>."],"key":"Д","review":["Сочетание со словом «уровень»","Вспомним, к чему относится пропущенное слово: «уровень … и мы сделаем всё для его …». Местоимение «его» отсылает к «уровню».","По-русски уровень повышают. Отношения можно укреплять или улучшать, но этому предложению нужно «повышения»."]},{"author":"Л. Фёдорова","question":"Вот названия некоторых частей дома (усадьбы): 1) <em>ворота</em>, 2) <em>крыльцо</em>, 3) <em>крыша</em>, 4) <em>окно</em>, 5) <em>наличник</em>, 6) <em>чердак</em>, 7) <em>черепица</em>. Какие из них исторически являются однокоренными с названиями частей тела?","choices":["1, 5","1, 4, 5, 7","2, 4, 5, 7","1, 2, 4, 5, 7","2, 3, 4, 5, 7."],"key":"В","review":["Дом и части тела","Сопоставь «крыльцо — крыло», «окно — око», «наличник — лицо», «черепица — череп». Здесь проверяются исторические связи; современное значение может сильно отличаться.","Соответствуют номера 2, 4, 5 и 7. Одного внешнего сходства с другим словом для такого вывода недостаточно."]},{"author":"Е. Муравенко","question":"Как можно прочитать «1,5» в предложении: <em>Дождь лил в течение 1,5 суток</em>?","choices":["<em>полтора</em>","<em>полторы</em>","<em>полутора</em>","<em>полуторы</em>","ни один из вариантов (А)–(Г) не подходит."],"key":"В","review":["В течение скольких суток","Предлог «в течение» требует родительного падежа: «в течение двух суток». У числительного «полтора» косвенная форма «полутора».","Получается «в течение полутора суток». Слово «суток» сохраняет родительный множественного."]},{"author":"И. Рубанов","question":"Какое словосочетание нужно поставить вместо многоточия во фразу: «<em>Это был ..., как медвежонок</em>»?","choices":["<em>некто иной</em>","<em>не кто иной</em>","<em>кто не иной</em>","<em>ни кто иной</em>","<em>никто иной</em>."],"key":"Б","review":["Как называют медвежонка","Проверь конструкцию с пояснением через «как»: «Это был не кто иной, как медвежонок». Здесь сочетание служит для отождествления.","Пишем не отдельно от кто. Форма «никто иной» появилась бы при отрицании: «никто иной этого не сделал»."]},{"author":"Я. Миронов","question":"Выберите фразу, где нет орфографических ошибок:","choices":["<em>Непогашенная конфорка стала причиной инцедента</em>.","<em>Непогашеная комфорка стала причиной инцидента</em>.","<em>Непогашеная конфорка стала причиной инциндента</em>.","<em>Не погашенная конфорка стала причиной инцедента</em>.","<em>Непогашенная конфорка стала причиной инцидента</em>."],"key":"Д","review":["Строчка без опечаток","Нужны написания «конфорка» через н и «инцидент» без второго н перед д. «Непогашенная» в данном сочетании пишется слитно и с двумя н.","Все три условия выполняются в строке «Непогашенная конфорка стала причиной инцидента»."]},{"author":"К. Кноп","question":"Первыми космонавтами Индии (И), Венгрии (В), Франции (Ф) и Германии (Г) были Берталан Фаркаш (1), Зигмунд Йен (2), Ракеш Шарма (3) и Жан Лу Кретьен (4). Выберите правильное соответствие космонавтов их родным странам.","choices":["И2, В1, Ф4, Г3","И3, В1, Ф4, Г2","И3, В1, Ф2, Г4","И1, В4, Ф3, Г2","И3, В2, Ф4, Г1."],"key":"Б","review":["Четыре космонавта","Ракеш Шарма представлял Индию, Берталан Фаркаш — Венгрию. Значит, первые два соответствия И3 и В1.","Жан-Лу Кретьен представлял Францию, Зигмунд Йен — Германию. Полный ряд И3, В1, Ф4, Г2."]},{"author":"Е. Муравенко и И. Рубанов","question":"Неделю длится русская масленица, и каждый день её замечателен по-своему. В среду — «лакомку» — едят блины да кулебяки, в пятницу — «тёщины посиделки» в гостях у матери жены, а в субботу — тоже посиделки, но уже у золовки. Кого же по традиции надо навестить вечером масленичной субботы?","choices":["<em>сестру мужа</em>","<em>сестру жены</em>","<em>жену брата</em>","<em>сестру матери</em>","<em>мать мужа</em>."],"key":"А","review":["Масленичная суббота","Золовкой называют сестру мужа. Тёща — мать жены, у неё другое название и другой день масленичного обычая.","«Золовкины посиделки» связаны с сёстрами мужа. Это указывает на нужное родство."]},{"author":"Е. Муравенко","question":"Сколько общих звуков в словах <em>свой</em> и <em>овсяный</em>?","choices":["0","1","2","3","4."],"key":"Б","review":["Одинаковые звуки","Ударное [о] в «свой» не совпадает по звучанию с безударным о в начале «овсяный». Перед глухим [с’] согласный в оглушается до [ф], а сам [с’] мягкий.","Оба слова заканчиваются [й]. Это их единственный общий звук при обычном произношении."]},{"author":"Л. Фёдорова","question":"Какие из названий головных уборов образованы в русском языке из исконных основ: 1) <em>панама</em>, 2) <em>шапокляк</em>, 3) <em>цилиндр</em>, 4) <em>бейсболка</em>, 5) <em>сомбреро</em>, 6) <em>берет</em>, 7) <em>треуголка</em>, 8) <em>шапка</em>, 9) <em>ушанка</em>?","choices":["1, 4, 6, 7, 8, 9","1, 6, 7, 8, 9","6, 7, 8, 9","7, 8, 9","7, 9."],"key":"Д","review":["Названия головных уборов","В словах «треуголка» и «ушанка» видны русские основы: три угла и уши. «Бейсболка» тоже образована с русским суффиксом, но её производящая основа «бейсбол» заимствована.","Если выбрать названия, образованные от указанных исконных основ, остаются треуголка и ушанка — 7 и 9."],"reviewedEdition":true},{"author":"Н. Муравенко","question":"Какие из перечисленных глаголов относятся к первому спряжению: 1) <em>захотеть</em>, 2) <em>вертеть</em>, 3) <em>выбежать</em>, 4) <em>подержать</em>, 5) <em>прочитать</em>, 6) <em>грести</em>?","choices":["5, 6","1, 2, 5, 6","1, 2, 3, 5, 6","3, 4","1, 5, 6."],"key":"А","review":["Личные окончания","«Прочитаешь, прочитают» и «гребёшь, гребут» имеют окончания первого спряжения. «Вертеть» и «держать» с производными относятся ко второму.","«Хотеть» и «бежать» с приставками сохраняют особенности разноспрягаемых глаголов. Получили номера 5 и 6."]},{"author":"Л. Фёдорова","question":"В каких словах выделяется окончание <em>-ий</em>: 1) <em>меньший</em>, 2) <em>вороний</em>, 3) <em>тихий</em>, 4) <em>учений</em>, 5) <em>не убий</em>?","choices":["в 1, 2, 3","во всех","в 1, 3, 5","в 1, 3, 4","в 1, 3."],"key":"Д","review":["Где -ий является окончанием","Сравни «меньший — меньшая» и «тихий — тихая»: -ий заменяется другим окончанием. В «вороний — воронья» звук й связан с суффиксом притяжательного прилагательного.","В «учений» и «не убий» сочетание букв тоже не такое окончание прилагательного. Остаются 1 и 3."]},{"author":"Е. Муравенко","question":"Сколько различных смыслов имеет предложение <em>Для дочери Нины Игорь принёс новые учебники и словари</em>?","choices":["1","2","3","4","5."],"key":"Г","review":["Для кого учебники","«Для дочери Нины» — либо для дочери, которую зовут Нина, либо для дочери женщины по имени Нина. Уже есть два толкования.","«Новые» относится только к учебникам или также к словарям. Умножаем 2 на 2 и получаем четыре прочтения."]},{"author":"А. Монастырский","question":"Сколько слов/словосочетаний (где <em>пол</em> означает половину) написано неправильно: <em>пол-задачи, в пол-оборота, пол Москвы, вполудрёме, не два не полтора</em>?","choices":["1","2","3","4","5."],"key":"Д","review":["Пять половинок","Нормативные написания: «ползадачи», «вполоборота», «пол-Москвы». Перед именем собственным пол- отделяется дефисом, перед обычным согласным з — нет.","Два других выражения пишутся «в полудрёме», «ни два ни полтора». Следовательно, исправить нужно все пять записей."]},{"author":"Е. Муравенко","question":"Даны предложения: 1) <em>Живя за границей, она постоянно испытывала ностальгию по родине</em>. 2) <em>Будучи истинным патриотом родины, он не покинул Россию</em>. 3) <em>Пожилая старушка села на скамейку</em>. 4) <em>Этот футболист – настоящий патриот своего клуба</em>. Примем значения: ностальгия — тоска по родине, патриот — человек, преданный родине. В каких предложениях при таком прочтении слова неоправданно повторяют один смысл?","choices":["1","3","1, 3","1, 2, 3","1, 2, 3, 4."],"key":"Г","review":["Повтор смысла","В классическом школьном разборе «ностальгия» трактуется как тоска по родине, «патриот» — как преданный родине человек, а «старушка» уже указывает на преклонный возраст.","По такому условию смысл повторяют уточнения в 1, 2 и 3. В 4 выражение «патриот своего клуба» использует слово в переносном значении."],"reviewedEdition":true},{"author":"Е. Муравенко","question":"Даны предложения: 1) <em>Занятия проводятся согласно расписания</em>. 2) <em>Этот стадион расположен в тридцати минут езды от города</em>. 3) <em>Никому не секрет, что Сергей пишет стихи</em>. 4) <em>Вопреки ожиданиям Андрей отлично выступил</em>. Укажите все предложения, содержащие ошибки в употреблении падежной формы.","choices":["2","2, 3","1, 2, 3","все предложения содержат ошибки","ни одно из предложений не содержит ошибок."],"key":"В","review":["Управление падежом","Нужно «согласно расписанию» (дательный), «в тридцати минутах езды» (предложный) и «ни для кого не секрет» (устойчивое сочетание).","«Вопреки ожиданиям» уже стоит в нужном дательном падеже. Ошибочны первые три предложения."]},{"author":"Е. Муравенко","question":"Даны соответствующие друг другу слова двух родственных языков — русские и сербскохорватские: <em>лев</em> — лав, <em>снег</em> — снег, <em>размер</em> — размер, <em>ветер</em> — ветар, <em>грозен</em> — грозан. Как будет по-сербскохорватски <em>век</em> и <em>борец</em>?","choices":["век, борец","век, борац","вак, борец","вак, борац","век, барац."],"key":"Б","review":["Как меняется гласная","В «лев — лав», «ветер — ветар», «грозен — грозан» русскому беглому е соответствует а. В «снег» гласная сохраняется.","В слове «век» е не беглое: «века». В «борец — борца» е беглое. По образцу получаем «век, борац»."]},{"author":"П. Аркадьев","question":"Ознакомьтесь с предложениями на японском языке и их переводами: хэя-ни хаха-га иру — <em>в комнате находится мама</em> хэя-ни цукуэ-га ару — <em>в комнате находится стол</em> нива-ни икэ-га ару — <em>во дворе находится пруд</em> нива-ни нэко-га иру — <em>во дворе находится кошка</em> икэ-ни сакана-га иру — <em>в пруду находится рыбка</em> Как переводится на японский язык предложение <em>в комнате находится собака</em>, если известно, что по-японски <em>собака —</em> ину?","choices":["ину-ни хэя-га иру","хэя-га ину-ни ару","хэя-ни ину-га иру","хэя-ни ину-га ару","хэя-ни ину-ни иру."],"key":"В","review":["Собака в комнате","После названия места ставится -ни, после названия находящегося там объекта — -га. Для живой кошки и рыбки дан глагол иру.","Подставляем «хэя» — комната и «ину» — собака: «хэя-ни ину-га иру»."]}], {"year":2001,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2001.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
